// Parse the AI response and extract opportunities
const response = $input.first().json;

// Get the content from the AI response
let content = response.choices[0].message.content;

// Try to parse as JSON, handling potential markdown code blocks
if (content.startsWith('```')) {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
}

try {
  const parsed = JSON.parse(content.trim());

  // Validate we have opportunities array
  if (!parsed.opportunities || !Array.isArray(parsed.opportunities)) {
    throw new Error('Invalid response structure: missing opportunities array');
  }

  // Ensure we have 4-8 opportunities
  const opportunities = parsed.opportunities.slice(0, 8);

  if (opportunities.length < 4) {
    console.warn(`Only ${opportunities.length} opportunities found, minimum is 4`);
  }

  return {
    json: {
      opportunities: opportunities,
      total: opportunities.length,
      original_content: $('Upload Blog Post').first().json['Blog Post (Markdown)'].data
    }
  };
} catch (error) {
  throw new Error(`Failed to parse AI response: ${error.message}. Content: ${content.substring(0, 500)}`);
}

// Split opportunities into individual items for parallel processing
const data = $input.first().json;
const opportunities = data.opportunities;

return opportunities.map((opp, index) => ({
  json: {
    opportunity: opp,
    index: index + 1,
    total: data.total,
    original_content: data.original_content
  }
}));

// Parse the prompt generator response
const response = $input.first().json;
const previousData = $('Split Opportunities').item;

let content = response.choices[0].message.content;

// Handle markdown code blocks
if (content.startsWith('```')) {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
}

try {
  const parsed = JSON.parse(content.trim());

  return {
    json: {
      ...parsed,
      index: previousData.json.index,
      total: previousData.json.total,
      original_opportunity: previousData.json.opportunity
    }
  };
} catch (error) {
  // If parsing fails, create a fallback prompt
  const opp = previousData.json.opportunity;
  return {
    json: {
      opportunity_id: opp.id,
      prompt: `Professional ${opp.visual_type} visualization showing ${opp.context}. ${opp.suggested_style} style, clean design, suitable for business blog. Data points: ${opp.data_points.join(', ')}. High quality, publication ready.`,
      negative_prompt: "blurry, low quality, amateur, cluttered, hard to read, watermark",
      aspect_ratio: "16:9",
      resolution: "2K",
      visual_type: opp.visual_type,
      filename_suggestion: `visual-${opp.id}-${opp.visual_type.toLowerCase().replace(/\s+/g, '-')}`,
      index: previousData.json.index,
      total: previousData.json.total,
      original_opportunity: opp,
      parse_error: error.message
    }
  };
}

// Store task info and prepare for status checking
const taskResponse = $input.first().json;
const promptData = $('Parse Prompt Response').item.json;

return {
  json: {
    taskId: taskResponse.taskId || taskResponse.data?.taskId || taskResponse.id,
    status: 'queued',
    checkCount: 0,
    maxChecks: 30,
    promptData: promptData,
    opportunity_id: promptData.opportunity_id,
    filename: promptData.filename_suggestion
  }
};

// Process status response and determine next action
const statusResponse = $input.first().json;

// Get previous task data - try multiple sources
let previousData;
try {
  previousData = $('Store Task Info').item?.json;
} catch (e) {
  // If Store Task Info not in path, get from Prepare Retry
  try {
    previousData = $('Prepare Retry').item?.json;
  } catch (e2) {
    previousData = {};
  }
}

// Extract status and image URL from response
const status = statusResponse.status || statusResponse.data?.status || 'unknown';
const imageUrl = statusResponse.output?.image_url || 
                 statusResponse.data?.output?.image_url ||
                 statusResponse.result?.url ||
                 statusResponse.data?.result?.url ||
                 statusResponse.output?.url ||
                 statusResponse.data?.output?.url ||
                 statusResponse.url ||
                 null;

const checkCount = (previousData.checkCount || 0) + 1;
const maxChecks = previousData.maxChecks || 30;

const isComplete = ['successful', 'completed', 'success', 'done'].includes(status.toLowerCase());
const isFailed = ['failed', 'error', 'cancelled'].includes(status.toLowerCase()) || checkCount >= maxChecks;
const shouldRetry = !isComplete && !isFailed;

return {
  json: {
    taskId: previousData.taskId,
    status: status,
    imageUrl: imageUrl,
    checkCount: checkCount,
    maxChecks: maxChecks,
    isComplete: isComplete,
    isFailed: isFailed,
    shouldRetry: shouldRetry,
    promptData: previousData.promptData,
    opportunity_id: previousData.opportunity_id,
    filename: previousData.filename,
    rawResponse: statusResponse
  }
};

// Prepare data for retry loop
const data = $input.first().json;

return {
  json: {
    taskId: data.taskId,
    checkCount: data.checkCount,
    maxChecks: data.maxChecks,
    promptData: data.promptData,
    opportunity_id: data.opportunity_id,
    filename: data.filename
  }
};

// Prepare success result
const driveResponse = $input.first().json;
const statusData = $('Process Status').item.json;

return {
  json: {
    success: true,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    drive_file_id: driveResponse.id,
    drive_url: driveResponse.webViewLink || driveResponse.webContentLink,
    original_quote: statusData.promptData?.original_opportunity?.quote
  }
};

// Handle failed image generation
const statusData = $input.first().json;

return {
  json: {
    success: false,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    error: statusData.isFailed ? 
      (statusData.checkCount >= statusData.maxChecks ? 'Timeout: max retries exceeded' : 'Generation failed') :
      'Unknown error',
    checkCount: statusData.checkCount,
    lastStatus: statusData.status,
    original_quote: statusData.promptData?.original_opportunity?.quote
  }
};

// Create final summary report
const allResults = $input.first().json.data;

const successful = allResults.filter(r => r.success);
const failed = allResults.filter(r => !r.success);

const summary = {
  total_opportunities: allResults.length,
  successful_generations: successful.length,
  failed_generations: failed.length,
  success_rate: Math.round((successful.length / allResults.length) * 100) + '%',
  generated_visuals: successful.map(s => ({
    opportunity_id: s.opportunity_id,
    visual_type: s.visual_type,
    filename: s.filename,
    drive_url: s.drive_url,
    quote: s.original_quote?.substring(0, 100) + '...'
  })),
  failed_visuals: failed.map(f => ({
    opportunity_id: f.opportunity_id,
    visual_type: f.visual_type,
    error: f.error,
    quote: f.original_quote?.substring(0, 100) + '...'
  })),
  timestamp: new Date().toISOString()
};

return { json: summary };

// Process retry status response
const statusResponse = $input.first().json;
const previousData = $('Prepare Retry').item.json;

// Extract status and image URL from response
const status = statusResponse.status || statusResponse.data?.status || 'unknown';
const imageUrl = statusResponse.output?.image_url || 
                 statusResponse.data?.output?.image_url ||
                 statusResponse.result?.url ||
                 statusResponse.data?.result?.url ||
                 statusResponse.output?.url ||
                 statusResponse.data?.output?.url ||
                 statusResponse.url ||
                 null;

const checkCount = (previousData.checkCount || 0) + 1;
const maxChecks = previousData.maxChecks || 30;

const isComplete = ['successful', 'completed', 'success', 'done'].includes(status.toLowerCase());
const isFailed = ['failed', 'error', 'cancelled'].includes(status.toLowerCase()) || checkCount >= maxChecks;
const shouldRetry = !isComplete && !isFailed;

return {
  json: {
    taskId: previousData.taskId,
    status: status,
    imageUrl: imageUrl,
    checkCount: checkCount,
    maxChecks: maxChecks,
    isComplete: isComplete,
    isFailed: isFailed,
    shouldRetry: shouldRetry,
    promptData: previousData.promptData,
    opportunity_id: previousData.opportunity_id,
    filename: previousData.filename,
    rawResponse: statusResponse
  }
};

// Prepare success result from retry
const driveResponse = $input.first().json;
const statusData = $('Process Retry Status').item.json;

return {
  json: {
    success: true,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    drive_file_id: driveResponse.id,
    drive_url: driveResponse.webViewLink || driveResponse.webContentLink,
    original_quote: statusData.promptData?.original_opportunity?.quote
  }
};

// Prepare for next retry iteration
const data = $input.first().json;

return {
  json: {
    taskId: data.taskId,
    checkCount: data.checkCount,
    maxChecks: data.maxChecks,
    promptData: data.promptData,
    opportunity_id: data.opportunity_id,
    filename: data.filename
  }
};

// Handle final failure after all retries exhausted
const statusData = $input.first().json;

return {
  json: {
    success: false,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    error: statusData.checkCount >= statusData.maxChecks ? 
      'Timeout: max retries exceeded (' + statusData.checkCount + ' checks)' : 
      'Generation failed with status: ' + statusData.status,
    checkCount: statusData.checkCount,
    lastStatus: statusData.status,
    original_quote: statusData.promptData?.original_opportunity?.quote
  }
};
